size_t size = huffman_codes.size();
outfile.write(reinterpret_cast<const char*>(&size), sizeof(size));

// For each character and its Huffman code
for (const auto& pair : huffman_codes) {
    unsigned char character = pair.first;
    const std::string& code = pair.second;
    size_t code_length = code.length();

    // Write the character (1 byte)
    outfile.write(reinterpret_cast<const char*>(&character), sizeof(character));

    // Write the code length (1 byte)
    outfile.write(reinterpret_cast<const char*>(&code_length), sizeof(code_length));

    // Write the code bits (packed into bytes)
    if (code_length > 0) {
        char byte = 0;
        int bit_count = 0;

        for (size_t i = 0; i < code_length; ++i) {
            // Set the bit if the character is '1'
            if (code[i] == '1') {
                byte |= (1 << (7 - bit_count));
            }
            bit_count++;

            // When we have a full byte, write it
            if (bit_count == 8) {
                outfile.write(&byte, sizeof(byte));
                byte = 0;
                bit_count = 0;
            }
        }

        // Write any remaining bits
        if (bit_count > 0) {
            outfile.write(&byte, sizeof(byte));
        }
    }
}

